  "guide.appGuide.subtitle": "ଘର, ଆର୍ଥିକ ନାଡ, ଏବଂ ବିଲ୍ ପ୍ରବେଶର ଏକ ସଂକ୍ଷିପ୍ତ ପଦକ୍ଷେପରେ | ଆପଣ ଯେକ time ଣସି ସମୟରେ ଷ୍ଟେପ୍ ଛାଡି ପାରନ୍ତି |",
