  "guide.setup.subtitle": "ଆପଣ କିପରି Perovo (ବେତନ ପ୍ରାପ୍ତ କିମ୍ବା ଘର) ବ୍ୟବହାର କରନ୍ତି ସମୀକ୍ଷା କରନ୍ତୁ ଏବଂ ଆୟ ମ ics ଳିକଗୁଡିକ ଅଦ୍ୟତନ କରନ୍ତୁ | ତୁମର ବିଲ୍ ସେପରି ରହିଥାଏ |",
