  "guide.completedNote": "ଏହି ଡିଭାଇସରେ ଶେଷ ଗାଇଡ୍ ସମାପ୍ତ ହୋଇଥିଲା | ଏହାକୁ ପୁଣି ଦେଖିବା ପାଇଁ ଉପରେ ଟ୍ୟାପ୍ କରନ୍ତୁ |",
  "guide.household.roomsLabel": "କୋଠରୀଗୁଡ଼ିକ କିପରି କାମ କରେ |",
  "guide.household.inviteTitle": "ଆପଣଙ୍କ ପରିବାର ଆମନ୍ତ୍ରଣ କୋଡ୍ |",
  "guide.household.inviteText": "ପରିବାର ସଦସ୍ୟଙ୍କ ସହିତ ଏହି 6-ଅକ୍ଷର କୋଡ୍ ଅଂଶୀଦାର କରନ୍ତୁ | ସେମାନେ Perovo କୁ ସାଇନ୍ ଇନ୍ କରନ୍ତି, Pro ଫାଇଲରେ ପାରିବାରିକ ମୋଡ୍ ଟର୍ନ୍ ଅନ୍ କରନ୍ତି, ଏବଂ ଆପଣଙ୍କ ରୁମରେ ଯୋଗଦେବା ପାଇଁ ଏହି କୋଡ୍ ପ୍ରବେଶ କରନ୍ତୁ |",
  "guide.household.shareTitle": "ଆପଣ ଯାହା ଅଂଶୀଦାର କରନ୍ତି ତାହା ନିୟନ୍ତ୍ରଣ କରନ୍ତୁ |",
  "guide.household.shareText": "ପରିବାର ସଦସ୍ୟ କ’ଣ ଦେଖିପାରିବେ ଆପଣ ସ୍ଥିର କରନ୍ତୁ | ଅନ୍ୟମାନଙ୍କୁ ଆପଣଙ୍କର ଦ daily ନନ୍ଦିନ ଖର୍ଚ୍ଚ ଦେଖିବା ପାଇଁ ଅଂଶୀଦାର ଟୋଗଲ୍ କରନ୍ତୁ | ଆପଣଙ୍କର ପ୍ରତିବଦ୍ଧତା ତାଲିକା ଅଂଶୀଦାର କରିବାକୁ ବିଲ୍ ନାମଗୁଡିକ ଟୋଗଲ୍ କରନ୍ତୁ |",
  "guide.household.outlookTitle": "ଘରର ଦୃଷ୍ଟିକୋଣ |",
  "guide.household.outlookText": "ଆପଣଙ୍କ ପରିବାର ପାଇଁ ମିଳିତ ଆର୍ଥିକ ସ୍ --ାସ୍ଥ୍ୟ - ଜରୁରୀକାଳୀନ ପାଣ୍ଠି କଭରେଜ୍, ଅଂଶୀଦାର ଚାପ ଏବଂ ଲକ୍ଷ୍ୟ | ଯେକ any ଣସି ସଦସ୍ୟଙ୍କ ତଥ୍ୟ ପରିବର୍ତ୍ତନ ହେଲେ ଅଦ୍ୟତନଗୁଡ଼ିକ |",
  "guide.pulse.label": "ଏହା କ’ଣ?",
  "guide.pulse.pressureTitle": "ଚାପ ସ୍କୋର |",
  "guide.pulse.pressureText": "ତୁମର ଆର୍ଥିକ ଚାପ ସ୍କୋର (0–100) ତୁମର ଆୟର କେତେ ସ୍ଥିର ବାଧ୍ୟତାମୂଳକକୁ ଯାଏ ତାହା ମାପ କରେ | 45 ତଳେ ସୁସ୍ଥ ଅଛି | 70 ରୁ ଅଧିକ ଅର୍ଥ ହେଉଛି ତୁମର ଦାୟିତ୍ heavy ଭାରୀ |",
  "guide.pulse.freeCashTitle": "Free ନଗଦ",
  "guide.pulse.freeCashText": "ଏହି ମାସରେ ଆପଣଙ୍କର ସମସ୍ତ ପ୍ରତିବଦ୍ଧ ଦେୟ ପରେ ଟଙ୍କା ବାକି ଅଛି | ଏହା ପ୍ରକୃତରେ ଆପଣଙ୍କୁ ଖର୍ଚ୍ଚ, ସଞ୍ଚୟ କିମ୍ବା ବିନିଯୋଗ କରିବାକୁ ପଡିବ |",
  "guide.pulse.survivalTitle": "ବଞ୍ଚାଅ ରନୱେ |",
  "guide.pulse.survivalText": "ଯଦି ତୁମେ ଆଜି ସମସ୍ତ ଆୟ ହରାଇଛ, ତୁମେ କେତେ ମାସ ସଞ୍ଚୟରୁ ତୁମର ବାଧ୍ୟତାମୂଳକ ବହନ କରିପାରିବ? 6+ ମାସ ହେଉଛି ଲକ୍ଷ୍ୟ |",
