  "privacy.title": "ଗୋପନୀୟତା ନୀତି",
  "privacy.effective": "ପ୍ରଭାବଶାଳୀ: ଜୁନ୍ 2026",
  "privacy.collectTitle": "ଆମେ କଣ ସଂଗ୍ରହ କରୁ |",
  "privacy.collectBody": "ନାମ, ଇମେଲ୍, ମୋବାଇଲ୍ ନମ୍ବର, ମାସିକ ଆୟ, PAN (ବ al କଳ୍ପିକ), ଆର୍ଥିକ ପ୍ରତିବଦ୍ଧତା, ending ଣ ରେକର୍ଡ, ମାସିକ ସ୍ନାପସଟ୍ ପ୍ରଦର୍ଶନ କରନ୍ତୁ |",
  "privacy.whyTitle": "ଆମେ କାହିଁକି ଏହାକୁ ସଂଗ୍ରହ କରୁ |",
  "privacy.whyBody": "କେବଳ ତୁମର ଆର୍ଥିକ ଚାପ ସ୍କୋର, ପ୍ରତିଶ୍ରୁତି ଭାର, ବଞ୍ଚିବା ରନୱେ, ଏବଂ ending ଣ ରେକର୍ଡ ଗଣନା କରିବାକୁ | ଅନ୍ୟ କ purpose ଣସି ଉଦ୍ଦେଶ୍ୟ ନାହିଁ |",
  "privacy.whereTitle": "ଯେଉଁଠାରେ ଏହା ଗଚ୍ଛିତ ଅଛି |",
  "privacy.whereBody": "ମୁଖ୍ୟତ your ଆପଣଙ୍କର ଡିଭାଇସରେ (ଲୋକାଲ୍ ଷ୍ଟୋରେଜ୍) | ବ Cloud କଳ୍ପିକ ଭାବରେ Supabase ରେ (ବିଶ୍ରାମ ସମୟରେ ଏନକ୍ରିପ୍ଟ, ପ୍ରତି ଉପଭୋକ୍ତା ପୃଥକ) ଯେତେବେଳେ କ୍ଲାଉଡ୍ ସିଙ୍କ ସକ୍ଷମ ହୁଏ |",
  "privacy.notTitle": "ଆମେ କଣ କରୁନାହୁଁ |",
  "privacy.notBody": "ଆମେ ଆପଣଙ୍କର ତଥ୍ୟ ବିକ୍ରୟ କରୁନାହୁଁ | ଆମେ କ୍ରେଡିଟ୍ ବ୍ୟୁରୋ ସହିତ ଅଂଶୀଦାର କରୁନାହୁଁ | ଆମେ ବିଜ୍ଞାପନ ପାଇଁ ତଥ୍ୟ ବ୍ୟବହାର କରୁନାହୁଁ | ରଜରପାଇ ଦେୟ ପରିଚାଳନା କରେ - Perovo ଆପଣଙ୍କ କାର୍ଡର ବିବରଣୀ କେବେବି ଦେଖେ ନାହିଁ |",
  "privacy.rightsTitle": "ଆପଣଙ୍କର ଅଧିକାର (DPDP ଅଧିନିୟମ 2023)",
  "privacy.rightsAccess": "ପ୍ରବେଶ: Pro ଫାଇଲ → ରପ୍ତାନି ତଥ୍ୟ |",
