  "insight.txn-small-leaks": "ଏହି ସପ୍ତାହରେ ଅନେକ ଛୋଟ କ୍ରୟ ଧୀରେ ଧୀରେ ମାସିକ ନମନୀୟତା ହ୍ରାସ କରିପାରେ |",
  "insight.txn-recurring-merchants": "{count} ବ୍ୟବସାୟୀମାନେ ଆପଣଙ୍କର ଲଗ୍ ହୋଇଥିବା ଖର୍ଚ୍ଚରୁ ବାରମ୍ବାର ଦେଖାଯାଉଛନ୍ତି - ଯଦି ବିଲ୍ ହେବା ଉଚିତ୍ ସମୀକ୍ଷା କରନ୍ତୁ |",
  "insight.txn-daily-budget-cap": "ବିଲ୍ ଆୟର ~ __T0 __% ବ୍ୟବହାର କରେ - ମାସର ଅବଶିଷ୍ଟ ସମୟ ପାଇଁ ଜୀବନଶ lifestyle ଳୀ ଖର୍ଚ୍ଚରେ ପ୍ରାୟ __T1 __ / ଦିନ ପାଇଁ ଲକ୍ଷ୍ୟ ରଖ |",
  "insight.txn-daily-budget-room": "ଦେୟ ପରେ, ଏହି ମାସର ଅବଶିଷ୍ଟ ସମୟ ପାଇଁ ପ୍ରାୟ __T0 __ / ଦିନ ନମନୀୟ ରହିଥାଏ |",
  "insight.txn-recurring-growth-high": "ବାରମ୍ବାର ବ al କଳ୍ପିକ ଖର୍ଚ୍ଚ ଧୀରେ ଧୀରେ ବ increasing ୁଛି - ଛୋଟ ପୁନରାବୃତ୍ତି ନମନୀୟତା ହ୍ରାସ କରିପାରେ |",
  "insight.txn-recurring-growth": "ବାରମ୍ବାର ବାଧ୍ୟତାମୂଳକଗୁଡିକ ଗତ ମାସରେ ପ୍ରାୟ __T0 __% ବୃଦ୍ଧି ପାଇଲା |",
  "insight.txn-under-pressure": "ବାଧ୍ୟତାମୂଳକ ଚାପ ବ ated ଼ିଥିବାବେଳେ ବିବେକାନନ୍ଦ ଦ daily ନିକ ଖର୍ଚ୍ଚ ଜାରି ରହିଛି |",
  "insight.txn-rhythm-unsafe": "ଏକ ଆଗାମୀ ସପ୍ତାହରେ ଘନ ଧାର୍ଯ୍ୟ ତାରିଖ ଅଛି - ଏହାକୁ ଏକ ଅଧିକ ବିପଦପୂର୍ଣ୍ଣ ନଗଦ ୱିଣ୍ଡୋ ଭାବରେ ବ୍ୟବହାର କରନ୍ତୁ |",
  "insight.txn-rhythm-overlap": "ପରବର୍ତ୍ତୀ ସପ୍ତାହରେ ଅନେକ ବାଧ୍ୟତାମୂଳକ ଅଲଗା ହୋଇଯାଏ - ସେମାନେ ଷ୍ଟକ୍ କରିବା ପୂର୍ବରୁ ନଗଦ ଯୋଜନା କରନ୍ତୁ |",
  "insight.txn-rhythm-lifestyle": "ସାମ୍ପ୍ରତିକ ଦ daily ନିକ ପତଳା ଜୀବନଶ lifestyle ଳୀ-ଭାରୀ ଖର୍ଚ୍ଚ କରେ - ବିଚକ୍ଷଣ ପ୍ରବାହ ନମନୀୟତା ହ୍ରାସ କରିପାରେ |",
  "insight.feed-restaurant-week": "ରେଷ୍ଟୁରାଣ୍ଟ ଏବଂ ବିତରଣ ଖର୍ଚ୍ଚ ଏହି ସପ୍ତାହରେ ବୃଦ୍ଧି କରାଯାଇଛି |",
  "insight.feed-medical-month": "ଏହି ମାସରେ ଚିକିତ୍ସା ଖର୍ଚ୍ଚ ସାଧାରଣ ଅପେକ୍ଷା ଅଧିକ |",
  "narrative.strength.repaymentRhythm": "ସାମ୍ପ୍ରତିକ ମାସଗୁଡିକରେ ସ୍ଥିର ପରିଶୋଧର ଗୀତ |",
