  "insight.family-dependency-burden": "{count} ଲୋକମାନେ ଏହି ଘର ଉପରେ ନିର୍ଭର କରନ୍ତି - ଜରୁରୀକାଳୀନ ଯୋଜନା ସମସ୍ତଙ୍କୁ ସୁରକ୍ଷା ଦେଇଥାଏ |",
